css:
.loader { display: flex; flex-direction: column; gap: calc(var(--loader-size) * .04); width: var(--loader-size); padding: calc(var(--loader-size) * .06); border-radius: calc(var(--loader-size) * .07); background: color-mix(in srgb, var(--loader-color) 12%, transparent); box-shadow: 0 calc(var(--loader-size) * .02) calc(var(--loader-size) * .05) rgba(15, 23, 42, .12); box-sizing: border-box; animation: twPulse calc(var(--loader-speed) * 1.8) cubic-bezier(.4, 0, .6, 1) infinite; }
.loader .head { width: 55%; height: calc(var(--loader-size) * .07); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 48%, transparent); }
.loader .body { height: calc(var(--loader-size) * .045); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 26%, transparent); }
.loader .actions { display: flex; justify-content: flex-end; gap: calc(var(--loader-size) * .04); margin-top: calc(var(--loader-size) * .03); }
.loader .actions i { width: 22%; height: calc(var(--loader-size) * .075); border-radius: calc(var(--loader-size) * .025); background: color-mix(in srgb, var(--loader-color) 38%, transparent); }
@keyframes twPulse { 50% { opacity: .5; } }
